// SPDX-License-Identifier: ISC

// Configuration: paste your key from https://jimaku.cc/profile between the quotes.
// A key saved in Jimaku Player's Settings takes precedence over this default.
// Keep this empty in published copies; never share a script containing your key.
const JIMAKU_API_KEY = '';

//
// Jimaku Player Reloaded 2.7.0 for Hachidori: Japanese subtitles from
// jimaku.cc over Crunchyroll's player, which Hachidori looks up like any text
// on the page. From https://github.com/mgp25/Jimaku-Player-Reloaded
// (jimaku-player-reloaded.js at 9dbb508dfe7d), based on the original Jimaku
// Player by sheodox (https://github.com/sheodox/jimaku-player). Changed for
// Hachidori, which runs a package on every page and gives it no
// GM_xmlhttpRequest:
// - it does nothing outside Crunchyroll, not even log;
// - it asks jimaku.cc with fetch, which jimaku.cc's CORS headers allow from
//   Crunchyroll's pages;
// - a click on a line no longer opens jisho.org, since Hachidori looks it up;
// - it marks its subtitles for Hachidori and hands it their timing, so that
//   with Hachidori's Crunchyroll mining switch on a note mined from a line
//   gets the line's audio and animation (search for "Hachidori").
//
// ISC License
//
// Copyright (c) 2026 mgp25
// Portions Copyright (c) 2020-2023 sheodox (https://github.com/sheodox/jimaku-player)
//
// Permission to use, copy, modify, and/or distribute this software for any
// purpose with or without fee is hereby granted, provided that the above
// copyright notice and this permission notice appear in all copies.
//
// THE SOFTWARE IS PROVIDED "AS IS" AND THE AUTHOR DISCLAIMS ALL WARRANTIES
// WITH REGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF
// MERCHANTABILITY AND FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR
// ANY SPECIAL, DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES
// WHATSOEVER RESULTING FROM LOSS OF USE, DATA OR PROFITS, WHETHER IN AN
// ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS ACTION, ARISING OUT OF
// OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS SOFTWARE.
(function () {
	'use strict';

	const IS_IFRAME = location.hostname === 'static.crunchyroll.com';
	const IS_MAIN = location.hostname === 'www.crunchyroll.com';
	// Hachidori runs a package on every page and in every frame.
	if (!IS_IFRAME && !IS_MAIN) return;
	const TAG = '[jimaku]';
	const log = (...a) => console.log(TAG, ...a);
	const warn = (...a) => console.warn(TAG, ...a);

	try { window.addEventListener('error', (e) => warn('uncaught', e.message)); } catch {}

	log('boot', location.hostname, IS_IFRAME ? '(iframe)' : '(main)');

	if (IS_IFRAME) {
		let video = null;
		let lastT = -1;
		const findVideo = () => {
			if (video && document.contains(video)) return video;
			video = document.querySelector('video');
			return video;
		};
		setInterval(() => {
			const v = findVideo();
			if (!v || typeof v.currentTime !== 'number') return;
			const t = Math.floor(v.currentTime * 1000);
			if (t !== lastT) {
				lastT = t;
				try {
					window.parent.postMessage(
						{ type: 'jp-time', time: t, paused: v.paused, duration: (v.duration || 0) * 1000 },
						'*'
					);
				} catch {
					/* ignore */
				}
			}
		}, 50);
		window.addEventListener('message', (e) => {
			const d = e.data;
			if (!d || typeof d !== 'object') return;
			const v = findVideo();
			if (!v) return;
			if (d.type === 'jp-seek' && typeof d.time === 'number') v.currentTime = d.time / 1000;
			if (d.type === 'jp-pause') v.pause();
			if (d.type === 'jp-play') v.play().catch(() => {});
		});
		return;
	}
	if (!IS_MAIN) return;

	const KEYS = {
		apiKey: 'jimaku-api-key',
		preferAss: 'jimaku-prefer-ass',
		entryCache: 'jimaku-entry-cache',
		alignBy: 'jimaku-alignment-by-show',
		fontScale: 'jimaku-font-scale',
		position: 'jimaku-position',
		hideNative: 'jimaku-hide-native-subs',
	};
	const get = (k, d) => {
		try {
			const raw = localStorage.getItem('jp:' + k);
			return raw == null ? d : JSON.parse(raw);
		} catch {
			return d;
		}
	};
	const set = (k, v) => {
		try {
			localStorage.setItem('jp:' + k, JSON.stringify(v));
		} catch (e) {
			warn('localStorage write failed', e);
		}
	};

	const state = {
		videoTimeMs: 0,
		videoFound: false,
		subtitles: [],
		subtitlesFile: '',
		subtitlesEpisode: '',
		alignment: 0,
		isEnabled: true,
		history: [],
		currentSubIndex: -1,
		detected: null,
		apiKey: get(KEYS.apiKey, JIMAKU_API_KEY.trim()),
		preferAss: get(KEYS.preferAss, true),
		fontScale: get(KEYS.fontScale, 1),
		position: get(KEYS.position, 'bottom'),
		hideNative: get(KEYS.hideNative, true),
		entryCache: get(KEYS.entryCache, {}),
		alignByShow: get(KEYS.alignBy, {}),
		entries: [],
		selectedEntry: null,
		files: [],
		ui: { panelOpen: false, tab: 'browse', loading: '', error: '' },
	};

	window.addEventListener('message', (e) => {
		if (!e.data || typeof e.data !== 'object') return;
		if (e.data.type === 'jp-time') {
			state.videoTimeMs = e.data.time;
			if (!state.videoFound) {
				state.videoFound = true;
				log('video connected');
				updateVideoStatus();
			}
		}
	});

	function postToPlayerIframe(message) {
		document.querySelectorAll('iframe').forEach((f) => {
			try {
				f.contentWindow.postMessage(message, '*');
			} catch {
				/* ignore */
			}
		});
	}
	function getLocalVideo() {
		return (
			document.querySelector('.bitmovinplayer-container video') ||
			document.querySelector('[class*="player"] video') ||
			document.querySelector('video')
		);
	}
	const seekTo = (timeMs) => {
		const t = Math.max(0, timeMs);
		const v = getLocalVideo();
		if (v) {
			v.currentTime = t / 1000;
			return;
		}
		postToPlayerIframe({ type: 'jp-seek', time: t });
	};

	setInterval(() => {
		const v = getLocalVideo();
		if (!v || typeof v.currentTime !== 'number') return;
		state.videoTimeMs = Math.floor(v.currentTime * 1000);
		if (!state.videoFound) {
			state.videoFound = true;
			log('local video connected', v);
			updateVideoStatus();
		}
	}, 50);

	function findBitmovinPlayer() {
		const c = document.querySelector('.bitmovinplayer-container');
		return c && c.player && typeof c.player === 'object' ? c.player : null;
	}
	function killBitmovinSubs(player) {
		if (!player || !player.subtitles || typeof player.subtitles.list !== 'function') return;
		try {
			const tracks = player.subtitles.list() || [];
			for (const t of tracks) {
				if (!t || !t.id) continue;
				try { player.subtitles.disable(t.id); } catch {}
			}
		} catch {}
	}
	function hookBitmovinEvents(player) {
		if (!player || player._jpHooked || typeof player.on !== 'function') return;
		player._jpHooked = true;
		const names = ['subtitleadded', 'subtitleenable', 'subtitleenabled', 'subtitlechanged', 'subtitlechange', 'sourceloaded'];
		for (const n of names) {
			try {
				player.on(n, () => {
					if (state.hideNative) killBitmovinSubs(player);
				});
			} catch {}
		}
		log('hooked bitmovin subtitle events');
	}
	function applyHideNative() {
		document.documentElement.classList.toggle('jp-hide-native', !!state.hideNative);
		const v = getLocalVideo();
		if (state.hideNative && v && v.textTracks) {
			for (let i = 0; i < v.textTracks.length; i++) {
				const t = v.textTracks[i];
				if (t.mode !== 'disabled') t.mode = 'disabled';
			}
		}
		const player = findBitmovinPlayer();
		if (player) {
			hookBitmovinEvents(player);
			if (state.hideNative) killBitmovinSubs(player);
		}
	}
	applyHideNative();
	setInterval(applyHideNative, 1000);

	const clean = (s) => (s || '').replace(/\s+/g, ' ').trim();

	function detectShow() {
		const out = { showTitle: '', showSlug: '', episodeNumber: null, episodeTitle: '', mediaId: '' };

		const urlMatch = location.pathname.match(/\/watch\/([A-Z0-9]+)(?:\/([^/?#]+))?/i);
		if (urlMatch) {
			out.mediaId = urlMatch[1];
			out.episodeTitle = urlMatch[2] ? urlMatch[2].replace(/-/g, ' ') : '';
		}

		const seriesLink = document.querySelector(
			'a[href*="/series/"], a[href*="/de/series/"], a[href*="/es/series/"], a[href*="/fr/series/"], a[href*="/it/series/"], a[href*="/pt-br/series/"], a[href*="/ru/series/"], a[href*="/ar/series/"], a[href*="/hi/series/"]'
		);
		if (seriesLink) {
			const m = seriesLink.getAttribute('href').match(/\/series\/([A-Z0-9]+)\/([^/?#]+)/i);
			if (m) {
				out.showSlug = m[2];
				out.showTitle = clean(seriesLink.textContent) || m[2].replace(/-/g, ' ');
			}
		}
		if (!out.showTitle) {
			const og = document.querySelector('meta[property="og:title"]');
			if (og && og.content) {
				out.showTitle = clean(og.content)
					.replace(/^Watch\s+/i, '')
					.replace(/\s*-\s*Crunchyroll\s*$/i, '');
			}
		}

		const sources = [
			document.querySelector('h1')?.textContent,
			document.querySelector('meta[property="og:title"]')?.content,
			document.title,
		].filter(Boolean);
		for (const s of sources) {
			const m = s.match(/(?:Episode|Ep\.?|E)\s*(\d+)/i);
			if (m) {
				out.episodeNumber = parseInt(m[1], 10);
				break;
			}
		}
		return out;
	}

	function refreshDetection() {
		const next = detectShow();
		const changed =
			!state.detected ||
			state.detected.showSlug !== next.showSlug ||
			state.detected.episodeNumber !== next.episodeNumber;
		state.detected = next;
		if (changed) {
			if (next.showSlug && typeof state.alignByShow[next.showSlug] === 'number') {
				state.alignment = state.alignByShow[next.showSlug];
				postToHachidori();
			}
			renderPanel();
		}
	}

	new MutationObserver(refreshDetection).observe(document.documentElement, { subtree: true, childList: true });
	refreshDetection();

	function normalize(text) {
		if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
		return text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
	}
	function parseTime(s) {
		if (!s) return 0;
		const c = s.trim().replace(',', '.').replace(/\s+/g, '');
		const parts = c.split(':');
		if (parts.length === 3)
			return Math.round(((parseInt(parts[0]) || 0) * 3600 + (parseInt(parts[1]) || 0) * 60 + (parseFloat(parts[2]) || 0)) * 1000);
		if (parts.length === 2) return Math.round(((parseInt(parts[0]) || 0) * 60 + (parseFloat(parts[1]) || 0)) * 1000);
		return 0;
	}
	const stripAss = (t) =>
		t
			.replace(/\{[^}]*\}/g, '')
			.replace(/\\N/gi, '\n')
			.replace(/\\n/gi, '\n')
			.replace(/\\h/gi, ' ')
			.trim();

	function parseSRT(content) {
		const subs = [];
		const blocks = normalize(content).split(/\n\n+/);
		for (const block of blocks) {
			const lines = block.split('\n');
			let ti = -1;
			for (let i = 0; i < Math.min(3, lines.length); i++) if (lines[i].includes('-->')) ti = i;
			if (ti < 0) continue;
			const arrow = lines[ti].indexOf('-->');
			const startStr = lines[ti].slice(0, arrow).trim();
			let endRaw = lines[ti].slice(arrow + 3).trim();
			const sp = endRaw.indexOf(' ');
			const endStr = sp > 0 ? endRaw.slice(0, sp) : endRaw;
			const start = parseTime(startStr);
			const end = parseTime(endStr);
			const text = lines.slice(ti + 1).join('\n').trim();
			if (text && end > start) subs.push({ start, end, text });
		}
		return subs.sort((a, b) => a.start - b.start);
	}
	function parseVTT(content) {
		let c = normalize(content);
		const headerEnd = c.indexOf('\n\n');
		if (headerEnd > 0) c = c.slice(headerEnd + 2);
		c = c.replace(/^NOTE[^\n]*\n([^\n]*\n)*/gm, '');
		return parseSRT(c);
	}
	function parseASS(content) {
		const subs = [];
		const lines = normalize(content).split('\n');
		let inEvents = false;
		let fields = [];
		for (const raw of lines) {
			const line = raw.trim();
			if (line.toLowerCase() === '[events]') {
				inEvents = true;
				continue;
			}
			if (line.startsWith('[') && line.endsWith(']')) {
				inEvents = false;
				continue;
			}
			if (!inEvents) continue;
			if (line.toLowerCase().startsWith('format:')) {
				fields = line
					.slice(7)
					.split(',')
					.map((f) => f.trim().toLowerCase());
			} else if (line.toLowerCase().startsWith('dialogue:')) {
				const dl = line.slice(9);
				const max = fields.length;
				const vals = [];
				let cur = '';
				let count = 0;
				for (let i = 0; i < dl.length; i++) {
					if (dl[i] === ',' && count < max - 1) {
						vals.push(cur.trim());
						cur = '';
						count++;
					} else cur += dl[i];
				}
				vals.push(cur.trim());
				const si = fields.indexOf('start');
				const ei = fields.indexOf('end');
				const ti = fields.indexOf('text');
				if (si >= 0 && ei >= 0 && ti >= 0) {
					const start = parseTime(vals[si]);
					const end = parseTime(vals[ei]);
					const text = stripAss(vals[ti] || '');
					if (text && end > start) subs.push({ start, end, text });
				}
			}
		}
		return subs.sort((a, b) => a.start - b.start);
	}
	function parseByName(content, filename) {
		const ext = (filename.split('.').pop() || '').toLowerCase();
		if (ext === 'ass' || ext === 'ssa') return parseASS(content);
		if (ext === 'vtt') return parseVTT(content);
		return parseSRT(content);
	}

	const API = 'https://jimaku.cc/api';

	// jimaku.cc answers Crunchyroll's pages with CORS headers (its API with
	// the Authorization header, its downloads to any page), so a plain fetch
	// reaches it from Hachidori's user-script world.
	async function gmReq(opts) {
		let response;
		try {
			response = await fetch(opts.url, {
				method: opts.method || 'GET',
				headers: opts.auth === false ? {} : { Authorization: state.apiKey },
				signal: AbortSignal.timeout(20000),
			});
		} catch (e) {
			throw new Error(e && e.name === 'TimeoutError' ? 'jimaku.cc request timed out' : 'Network error contacting jimaku.cc');
		}
		if (!response.ok) throw new Error(`HTTP ${response.status} from jimaku.cc`);
		return response.text();
	}
	async function jimakuSearch(query) {
		if (!state.apiKey) throw new Error('Set your jimaku.cc API key in Settings.');
		const text = await gmReq({ url: `${API}/entries/search?anime=true&query=${encodeURIComponent(query)}` });
		return JSON.parse(text);
	}
	async function jimakuFiles(entryId, episode) {
		if (!state.apiKey) throw new Error('Set your jimaku.cc API key in Settings.');
		const ep = typeof episode === 'number' ? `?episode=${episode}` : '';
		const text = await gmReq({ url: `${API}/entries/${entryId}/files${ep}` });
		return JSON.parse(text);
	}
	async function jimakuDownload(url) {
		return await gmReq({ url, auth: false });
	}

	function findPlayerContainer() {
		const iframe = document.querySelector('iframe[src*="static.crunchyroll.com"]');
		if (iframe) return iframe.parentElement;
		const v = document.querySelector('video');
		if (v) return v.closest('[class*="player"], [class*="video"]') || v.parentElement;
		return null;
	}

