	var host = null;
	var fab = null;
	var panel = null;
	var overlay = null;

	function ensureStyles() {
		if (document.getElementById('jp-styles')) return;
		const s = document.createElement('style');
		s.id = 'jp-styles';
		s.textContent = STYLES;
		document.head.appendChild(s);
	}

	function ensureMounted() {
		ensureStyles();
		const container = findPlayerContainer();
		if (!container) return false;

		const cs = getComputedStyle(container);
		if (cs.position === 'static') container.style.position = 'relative';

		if (!host || !container.contains(host)) {
			host = document.createElement('div');
			host.id = 'jp-host';
			// Hachidori hides this drawing while it records an animation of a line.
			host.dataset.hachidoriOverVideo = '';
			host.style.cssText = 'position:absolute;inset:0;pointer-events:none;';
			container.appendChild(host);

			overlay = document.createElement('div');
			overlay.id = 'jp-overlay';
			overlay.className = state.position;
			// Hachidori's subtitles and their line (Crunchyroll mining).
			overlay.dataset.hachidoriSubtitles = '';
			overlay.innerHTML = '<span id="jp-overlay-text" data-hachidori-subtitle-line></span>';
			host.appendChild(overlay);

			fab = document.createElement('button');
			fab.id = 'jp-fab';
			fab.type = 'button';
			fab.textContent = '字';
			fab.title = 'Jimaku Player (J)';
			fab.addEventListener('click', (e) => {
				e.stopPropagation();
				togglePanel();
			});
			fab.addEventListener('mousedown', (e) => e.stopPropagation());
			host.appendChild(fab);

			panel = document.createElement('div');
			panel.id = 'jp-panel';
			// Don't let any click/mouse interaction inside the panel reach the
			// Bitmovin player below (it pauses on click).
			['click', 'mousedown', 'mouseup', 'dblclick'].forEach((evt) => {
				panel.addEventListener(evt, (e) => e.stopPropagation());
			});
			host.appendChild(panel);

			const subTextEl = overlay.querySelector('#jp-overlay-text');
			subTextEl.addEventListener('mousedown', (e) => e.stopPropagation());
			// A click on a line stays off the player, which pauses on click;
			// Hachidori looks the line's words up.
			subTextEl.addEventListener('click', (e) => e.stopPropagation());

			document.documentElement.style.setProperty('--jp-scale', String(state.fontScale));
			renderPanel();
			log('mounted on player container', container);
		}
		return true;
	}

	function togglePanel(force) {
		const open = typeof force === 'boolean' ? force : !state.ui.panelOpen;
		state.ui.panelOpen = open;
		if (panel) panel.classList.toggle('open', open);
		if (fab) fab.classList.toggle('has-active', open);
		if (open) renderPanel();
	}

	function setLoading(label) {
		state.ui.loading = label;
		state.ui.error = '';
		renderPanel();
	}
	function setError(msg) {
		state.ui.loading = '';
		state.ui.error = msg;
		renderPanel();
	}
	function clearMessages() {
		state.ui.loading = '';
		state.ui.error = '';
	}

	function updateVideoStatus() {
		if (fab) fab.classList.toggle('has-subs', state.subtitles.length > 0);
	}

	function renderPanel() {
		if (!panel) return;
		const det = state.detected || {};
		const tab = state.ui.tab;
		const hasKey = !!state.apiKey;

		const tabsHtml = `
			<div class="tabs">
				<button data-tab="browse" class="${tab === 'browse' ? 'active' : ''}">Browse</button>
				<button data-tab="file" class="${tab === 'file' ? 'active' : ''}">File</button>
				<button data-tab="sync" class="${tab === 'sync' ? 'active' : ''}">Sync</button>
				<button data-tab="settings" class="${tab === 'settings' ? 'active' : ''}">Settings</button>
			</div>`;

		let body = '';
		if (tab === 'browse') body = renderBrowseTab(det, hasKey);
		else if (tab === 'file') body = renderFileTab();
		else if (tab === 'sync') body = renderSyncTab();
		else if (tab === 'settings') body = renderSettingsTab();

		panel.innerHTML = `
			<header>
				<span class="title">字幕プレーヤー</span>
				<button id="jp-close" title="Close">×</button>
			</header>
			${tabsHtml}
			<div class="tab-body">${body}</div>
			<div class="footer">
				<span class="muted">
					${state.subtitles.length ? `${state.subtitles.length} subs · offset ${(state.alignment / 1000).toFixed(2)}s` : 'No subtitles loaded'}
				</span>
				<span class="muted">${state.videoFound ? '● video' : '○ video'}</span>
			</div>`;

		panel.querySelector('#jp-close').onclick = () => togglePanel(false);
		panel.querySelectorAll('.tabs button').forEach((b) => {
			b.onclick = () => {
				state.ui.tab = b.dataset.tab;
				clearMessages();
				renderPanel();
			};
		});
		bindPanelHandlers(tab);
	}

	function renderBrowseTab(det, hasKey) {
		if (!hasKey) {
			return `
				<div class="stack">
					<p>Add your jimaku.cc API key in <strong>Settings</strong> to browse and download subtitles.</p>
					<p class="muted">Get one at <a target="_blank" rel="noopener noreferrer" href="https://jimaku.cc/profile">jimaku.cc/profile</a>.</p>
				</div>`;
		}
		const detLine = det.showTitle
			? `<p class="muted">Detected: <strong>${escapeHtml(det.showTitle)}</strong>${
					det.episodeNumber ? ` · Ep ${det.episodeNumber}` : ''
				}</p>`
			: `<p class="muted">No show detected from page — type one below.</p>`;

		const queryDefault = state.ui.queryDraft ?? det.showTitle ?? '';
		const epDefault = state.ui.episodeDraft ?? (det.episodeNumber ?? '');

		const search = `
			<div class="row">
				<input id="jp-query" type="text" value="${escapeAttr(queryDefault)}" placeholder="Show title">
				<input id="jp-ep" type="number" min="0" max="9999" value="${escapeAttr(String(epDefault))}" title="Episode">
				<button class="btn primary" id="jp-search-btn">Search</button>
			</div>`;

		let entries = '';
		if (state.entries.length > 1 && !state.selectedEntry) {
			entries = `<ul class="list">${state.entries
				.map(
					(e) => `<li data-entry-id="${e.id}">
				<div class="meta">
					<div class="name">${escapeHtml(e.name)}</div>
					${e.english_name && e.english_name !== e.name ? `<div class="muted">${escapeHtml(e.english_name)}</div>` : ''}
				</div>
				${e.flags?.unverified ? '<span class="pill unverified">Unverified</span>' : ''}
				${e.flags?.movie ? '<span class="pill">Movie</span>' : ''}
			</li>`
				)
				.join('')}</ul>`;
		}

		let files = '';
		if (state.selectedEntry) {
			const sortedFiles = sortFiles(state.files, state.preferAss);
			files = `
				<div class="row" style="margin-top:8px;">
					<strong style="flex:1">${escapeHtml(state.selectedEntry.name)}</strong>
					<button class="btn" id="jp-change-show">Change</button>
				</div>
				${
					sortedFiles.length
						? `<ul class="list">${sortedFiles
								.map(
									(f, i) => `<li data-file-idx="${i}">
									<div class="meta">
										<div class="name" title="${escapeAttr(f.name)}">${escapeHtml(f.name)}</div>
										<div class="muted">${formatSize(f.size)} · ${formatDate(f.last_modified)}</div>
									</div>
									${tagsForFile(f.name)}
								</li>`
								)
								.join('')}</ul>`
						: `<p class="muted" style="margin-top:6px">No files for episode ${epDefault || '?'}. <button class="btn" id="jp-show-all">Show all</button></p>`
				}
			`;
		}

		return `
			<div class="stack">
				${detLine}
				${search}
				${state.ui.loading ? `<p class="muted">${escapeHtml(state.ui.loading)}…</p>` : ''}
				${state.ui.error ? `<p class="err">${escapeHtml(state.ui.error)}</p>` : ''}
				${entries}
				${files}
			</div>`;
	}

	function renderFileTab() {
		return `
			<div class="stack">
				<p>Load a subtitle file from your computer.</p>
				<div class="row">
					<input id="jp-file-input" type="file" accept=".srt,.ass,.ssa,.vtt" style="flex:1">
				</div>
				${state.subtitlesFile ? `<p class="ok">Loaded: ${escapeHtml(state.subtitlesFile)} (${state.subtitles.length} lines)</p>` : ''}
				${state.ui.error ? `<p class="err">${escapeHtml(state.ui.error)}</p>` : ''}
			</div>`;
	}

	function renderSyncTab() {
		const a = (state.alignment / 1000).toFixed(2);
		const help =
			state.alignment === 0
				? 'Subtitles use the video timing.'
				: state.alignment > 0
				? `Subtitles delayed by ${a}s.`
				: `Subtitles hastened by ${(-state.alignment / 1000).toFixed(2)}s.`;

		const subs = state.subtitles;
		let nowBlock = '';
		if (subs.length) {
			const t = state.videoTimeMs + state.alignment;
			const curIdx = findSubIndex(t);
			let nextIdx = curIdx >= 0 ? curIdx + 1 : subs.findIndex((s) => s.start > t);
			if (nextIdx >= subs.length) nextIdx = -1;
			const curText = curIdx >= 0 ? subs[curIdx].text : '— (no subtitle showing)';
			const nextLine =
				nextIdx >= 0
					? `In ${((subs[nextIdx].start - t) / 1000).toFixed(1)}s: ${escapeHtml(subs[nextIdx].text.split('\n')[0]).slice(0, 60)}`
					: '— (end of subtitles)';
			nowBlock = `
				<div class="muted" style="border:1px solid #2a2d3a;border-radius:6px;padding:8px">
					<div style="color:#fff">${escapeHtml(curText.split('\n')[0]).slice(0, 80)}</div>
					<div style="margin-top:4px">${nextLine}</div>
				</div>`;
		}

		return `
			<div class="stack">
				<p class="muted">Current offset: <strong>${a}s</strong> — ${help}</p>
				${nowBlock}
				<button class="btn primary" id="jp-anchor-current" ${subs.length ? '' : 'disabled'}>Anchor sub to NOW <kbd>S</kbd></button>
				<button class="btn" id="jp-anchor-first" ${subs.length ? '' : 'disabled'}>Anchor first sub to NOW</button>
				<p class="muted">
					<strong>Fastest way:</strong> while watching, press <kbd>S</kbd> the instant you hear a line begin. The currently-shown (or next upcoming) subtitle gets snapped to that moment. Press <kbd>B</kbd> right after to rewind and verify. The "first sub" button is for episode starts where no sub is showing yet.
				</p>

				<div class="align-grid">
					<button class="btn" data-shift="-1000">−1.0s (subs earlier)</button>
					<button class="btn" data-shift="1000">+1.0s (subs later)</button>
					<button class="btn" data-shift="-200">−0.2s</button>
					<button class="btn" data-shift="200">+0.2s</button>
				</div>
				<div class="row">
					<button class="btn" id="jp-reset-align">Reset to 0</button>
					<button class="btn" id="jp-rewind">⏪ Rewind to last sub <kbd>B</kbd></button>
				</div>
				<p class="muted">Hotkeys: <kbd>Z</kbd>/<kbd>X</kbd> nudge ±0.2s · with <kbd>Shift</kbd> ±1s.</p>
			</div>`;
	}

	function renderSettingsTab() {
		return `
			<div class="stack">
				<label>jimaku.cc API key</label>
				<div class="row">
					<input id="jp-apikey" type="password" autocomplete="off" placeholder="Paste your API key" value="${escapeAttr(state.apiKey)}">
					<button class="btn primary" id="jp-save-key">Save</button>
				</div>
				<p class="muted">Get one at <a target="_blank" rel="noopener noreferrer" href="https://jimaku.cc/profile">jimaku.cc/profile</a>. Stored locally only.</p>

				<label class="row" style="margin-top:8px"><input type="checkbox" id="jp-prefer-ass" ${state.preferAss ? 'checked' : ''}> Prefer ASS files when available</label>

				<label>Subtitle font scale (${Math.round(state.fontScale * 100)}%)</label>
				<input id="jp-scale" type="range" min="0.6" max="2.5" step="0.1" value="${state.fontScale}">

				<label>Position</label>
				<div class="row">
					<button class="btn" data-pos="bottom" ${state.position === 'bottom' ? 'style="background:#e83450"' : ''}>Bottom</button>
					<button class="btn" data-pos="top" ${state.position === 'top' ? 'style="background:#e83450"' : ''}>Top</button>
				</div>

				<p class="muted">Hotkeys: <kbd>S</kbd> sync · <kbd>B</kbd> rewind to last sub · <kbd>J</kbd> open panel · <kbd>H</kbd> hide subs · <kbd>I</kbd> flip position · <kbd>Z</kbd>/<kbd>X</kbd> nudge ±0.2s (Shift = ±1s).</p>
			</div>`;
	}

	function bindPanelHandlers(tab) {
		if (tab === 'browse') {
			const q = panel.querySelector('#jp-query');
			const e = panel.querySelector('#jp-ep');
			if (q) q.addEventListener('input', () => (state.ui.queryDraft = q.value));
			if (e)
				e.addEventListener('input', () => (state.ui.episodeDraft = e.value ? parseInt(e.value, 10) : ''));
			panel.querySelector('#jp-search-btn')?.addEventListener('click', doSearch);
			q?.addEventListener('keydown', (ev) => ev.key === 'Enter' && doSearch());
			panel.querySelectorAll('[data-entry-id]').forEach((li) => {
				li.onclick = () => pickEntry(parseInt(li.dataset.entryId, 10));
			});
			panel.querySelector('#jp-change-show')?.addEventListener('click', () => {
				state.selectedEntry = null;
				state.files = [];
				if (state.detected?.showSlug) {
					delete state.entryCache[state.detected.showSlug];
					set(KEYS.entryCache, state.entryCache);
				}
				renderPanel();
			});
			panel.querySelector('#jp-show-all')?.addEventListener('click', () => loadFiles(undefined));
			panel.querySelectorAll('[data-file-idx]').forEach((li) => {
				li.onclick = () => loadFileFromList(parseInt(li.dataset.fileIdx, 10));
			});
		} else if (tab === 'file') {
			panel.querySelector('#jp-file-input')?.addEventListener('change', onFileChosen);
		} else if (tab === 'sync') {
			panel.querySelectorAll('[data-shift]').forEach((b) => {
				b.onclick = () => adjustAlignment(parseInt(b.dataset.shift, 10));
			});
			panel.querySelector('#jp-reset-align')?.addEventListener('click', () => {
				state.alignment = 0;
				persistAlignment();
				renderPanel();
			});
			panel.querySelector('#jp-rewind')?.addEventListener('click', rewindToLastSub);
			panel.querySelector('#jp-anchor-first')?.addEventListener('click', anchorFirstSub);
			panel.querySelector('#jp-anchor-current')?.addEventListener('click', anchorCurrentSub);
		} else if (tab === 'settings') {
			panel.querySelector('#jp-save-key')?.addEventListener('click', () => {
				state.apiKey = panel.querySelector('#jp-apikey').value.trim();
				set(KEYS.apiKey, state.apiKey);
				toast('API key saved');
				renderPanel();
			});
			panel.querySelector('#jp-prefer-ass')?.addEventListener('change', (ev) => {
				state.preferAss = ev.target.checked;
				set(KEYS.preferAss, state.preferAss);
				renderPanel();
			});
			panel.querySelector('#jp-scale')?.addEventListener('input', (ev) => {
				state.fontScale = parseFloat(ev.target.value);
				document.documentElement.style.setProperty('--jp-scale', String(state.fontScale));
				set(KEYS.fontScale, state.fontScale);
				renderPanel();
			});
			panel.querySelectorAll('[data-pos]').forEach((b) => {
				b.onclick = () => {
					state.position = b.dataset.pos;
					set(KEYS.position, state.position);
					if (overlay) overlay.className = state.position;
					renderPanel();
				};
			});
		}
	}

	async function doSearch() {
		const det = state.detected || {};
		const query = (state.ui.queryDraft ?? det.showTitle ?? '').trim();
		if (!query) {
			setError('Type a show title to search.');
			return;
		}
		state.entries = [];
		state.selectedEntry = null;
		state.files = [];
		setLoading('Searching jimaku.cc');
		try {
			const list = await jimakuSearch(query);
			state.entries = list || [];
			clearMessages();

			if (state.entries.length === 0) {
				setError(`No matches for "${query}".`);
				return;
			}
			const cached = det.showSlug ? state.entryCache[det.showSlug] : null;
			const cacheHit = cached ? state.entries.find((e) => e.id === cached) : null;
			const exact =
				!cacheHit &&
				state.entries.find(
					(e) => !e.flags?.unverified && (e.name === query || e.english_name === query)
				);
			const auto = cacheHit || exact || (state.entries.length === 1 ? state.entries[0] : null);
			if (auto) await pickEntry(auto.id);
			else renderPanel();
		} catch (e) {
			setError(e.message);
		}
	}
	async function pickEntry(entryId) {
		const entry = state.entries.find((x) => x.id === entryId);
		if (!entry) return;
		state.selectedEntry = entry;
		if (state.detected?.showSlug) {
			state.entryCache[state.detected.showSlug] = entry.id;
			set(KEYS.entryCache, state.entryCache);
		}
		const ep = state.ui.episodeDraft ?? state.detected?.episodeNumber;
		await loadFiles(typeof ep === 'number' ? ep : undefined);
	}
	async function loadFiles(episode) {
		if (!state.selectedEntry) return;
		setLoading('Loading files');
		try {
			state.files = await jimakuFiles(state.selectedEntry.id, episode);
			clearMessages();
			renderPanel();
		} catch (e) {
			setError(e.message);
		}
	}
	async function loadFileFromList(idx) {
		const sorted = sortFiles(state.files, state.preferAss);
		const f = sorted[idx];
		if (!f) return;
		const ext = (f.name.split('.').pop() || '').toLowerCase();
		if (!['srt', 'vtt', 'ass', 'ssa'].includes(ext)) {
			setError(`Unsupported file: .${ext}`);
			return;
		}
		setLoading(`Downloading ${f.name}`);
		try {
			const text = await jimakuDownload(f.url);
			applySubs(parseByName(text, f.name), f.name);
			toast(`Loaded ${f.name}`);
			togglePanel(false);
		} catch (e) {
			setError(e.message);
		}
	}
	function onFileChosen(ev) {
		const file = ev.target.files?.[0];
		if (!file) return;
		const reader = new FileReader();
		reader.onload = () => {
			const subs = parseByName(reader.result, file.name);
			applySubs(subs, file.name);
			toast(`Loaded ${file.name}`);
			togglePanel(false);
		};
		reader.onerror = () => setError('Failed to read file');
		reader.readAsText(file, 'UTF-8');
	}

	function applySubs(subs, filename) {
		state.subtitles = subs;
		state.subtitlesFile = filename;
		// The episode the file is for, which Hachidori keeps its timing under.
		state.subtitlesEpisode = detectShow().mediaId;
		state.history = [];
		state.currentSubIndex = -1;
		updateVideoStatus();
		renderPanel();
		postToHachidori();
	}

	// Hachidori (https://github.com/bee-san/hachidori) reads the lines with its
	// popup dictionary. With its Crunchyroll mining switch on, it also takes
	// their timing from here, as WebVTT in the video's own time (this script's
	// offset applied), so a note mined from a line gets the whole line, its
	// audio and its animation. It asks again when it missed a post.
	const HACHIDORI_PAGE = 'hachidori-crunchyroll-page';
	const HACHIDORI_COMMAND = 'hachidori-crunchyroll-command';
	function vttTime(ms) {
		const t = Math.max(0, Math.round(ms));
		const pad = (n, width) => String(n).padStart(width, '0');
		return `${pad(Math.floor(t / 3600000), 2)}:${pad(Math.floor(t / 60000) % 60, 2)}:${pad(Math.floor(t / 1000) % 60, 2)}.${pad(t % 1000, 3)}`;
	}
	// A line's text as WebVTT cue text: escaped, and without blank lines, which would end the cue.
	const vttText = (text) =>
		text
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;')
			.split('\n')
			.map((line) => line.trim())
			.filter(Boolean)
			.join('\n');
	function postToHachidori() {
		if (!state.subtitlesEpisode || !state.subtitles.length) return;
		const cues = state.subtitles
			.map((sub) => ({ start: sub.start - state.alignment, end: sub.end - state.alignment, text: vttText(sub.text) }))
			.filter((cue) => cue.end > 0 && cue.text);
		const text = 'WEBVTT\n\n' + cues.map((cue) => `${vttTime(cue.start)} --> ${vttTime(cue.end)}\n${cue.text}`).join('\n\n') + '\n';
		document.dispatchEvent(
			new CustomEvent(HACHIDORI_PAGE, {
				detail: JSON.stringify({ kind: 'subtitle', movieId: state.subtitlesEpisode, trackId: 'jimaku', closedCaptions: false, format: 'webvtt', text }),
			})
		);
	}
	document.addEventListener(HACHIDORI_COMMAND, (event) => {
		let command;
		try {
			command = JSON.parse(event.detail);
		} catch {
			return;
		}
		if (command && command.type === 'resend' && command.movieId === state.subtitlesEpisode) postToHachidori();
	});

	function adjustAlignment(deltaMs) {
		state.alignment += deltaMs;
		persistAlignment();
		renderPanel();
	}
	function persistAlignment() {
		const slug = state.detected?.showSlug;
		if (slug) {
			state.alignByShow[slug] = state.alignment;
			set(KEYS.alignBy, state.alignByShow);
		}
		postToHachidori();
	}

	function rewindToLastSub() {
		const last = state.history[0];
		if (last) seekTo(last.start - state.alignment);
	}

	function pulseFab() {
		if (!fab) return;
		fab.classList.remove('pulse');
		void fab.offsetWidth;
		fab.classList.add('pulse');
	}

	function anchorFirstSub() {
		if (!state.subtitles.length) {
			toast('No subtitles loaded');
			return;
		}
		state.alignment = state.subtitles[0].start - state.videoTimeMs;
		persistAlignment();
		const preview = state.subtitles[0].text.split('\n')[0].slice(0, 40);
		toast(`✓ First sub anchored: "${preview}"`);
		pulseFab();
		renderPanel();
	}
	function anchorCurrentSub() {
		if (!state.subtitles.length) {
			toast('No subtitles loaded');
			return;
		}
		const t = state.videoTimeMs + state.alignment;
		let idx = findSubIndex(t);
		if (idx < 0) {
			idx = state.subtitles.findIndex((s) => s.start > t);
			if (idx < 0) idx = state.subtitles.length - 1;
		}
		const target = state.subtitles[idx];
		state.alignment = target.start - state.videoTimeMs;
		persistAlignment();
		const preview = target.text.split('\n')[0].slice(0, 40);
		toast(`✓ Anchored: "${preview}"`);
		pulseFab();
		renderPanel();
	}

	function sortFiles(list, preferAss) {
		const score = (f) => {
			const n = f.name.toLowerCase();
			let s = 0;
			if (preferAss && /\.(ass|ssa)$/.test(n)) s += 5;
			if (/web|crunchy|amazon|netflix|subsplease|erai-raws/.test(n)) s += 3;
			if (/\.srt$/.test(n)) s += 1;
			if (/\.7z$|\.zip$|\.rar$/.test(n)) s -= 10;
			if (/\.sup(\.|$)/.test(n)) s -= 8;
			return s;
		};
		return [...list].sort((a, b) => score(b) - score(a));
	}
	function tagsForFile(name) {
		const out = [];
		if (/\.(ass|ssa)$/i.test(name)) out.push('<span class="pill ass">ASS</span>');
		if (/web|crunchy|amazon|netflix/i.test(name)) out.push('<span class="pill web">WEB</span>');
		if (/bd|bluray|blu-ray/i.test(name)) out.push('<span class="pill bd">BD</span>');
		return out.join('');
	}
	const formatSize = (b) =>
		b < 1024 ? `${b} B` : b < 1048576 ? `${(b / 1024).toFixed(1)} KB` : `${(b / 1048576).toFixed(2)} MB`;
	const formatDate = (s) => {
		try {
			return new Date(s).toLocaleDateString();
		} catch {
			return s;
		}
	};
	function escapeHtml(s) {
		return String(s ?? '').replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
	}
	const escapeAttr = escapeHtml;

	function tick() {
		if (!overlay) return;
		const el = overlay.querySelector('#jp-overlay-text');
		if (!state.isEnabled || state.subtitles.length === 0) {
			if (el) {
				el.textContent = '';
				el.style.display = 'none';
			}
			return;
		}
		const t = state.videoTimeMs + state.alignment;
		const idx = findSubIndex(t);
		if (idx >= 0) {
			const sub = state.subtitles[idx];
			if (el && el.textContent !== sub.text) el.textContent = sub.text;
			if (el) el.style.display = 'inline-block';
			if (idx !== state.currentSubIndex) {
				state.currentSubIndex = idx;
				state.history = [sub, ...state.history.slice(0, 9)];
			}
		} else {
			if (el) {
				el.textContent = '';
				el.style.display = 'none';
			}
			state.currentSubIndex = -1;
		}
	}
	function findSubIndex(t) {
		const a = state.subtitles;
		let lo = 0;
		let hi = a.length - 1;
		while (lo <= hi) {
			const mid = (lo + hi) >> 1;
			const s = a[mid];
			if (t < s.start) hi = mid - 1;
			else if (t > s.end) lo = mid + 1;
			else return mid;
		}
		return -1;
	}

	let toastEl;
	function toast(msg) {
		if (!toastEl) {
			toastEl = document.createElement('div');
			toastEl.style.cssText =
				'position:fixed;left:50%;top:24px;transform:translateX(-50%);background:#222;color:#fff;padding:8px 14px;border-radius:6px;font:13px sans-serif;z-index:2147483647;opacity:0;transition:opacity .2s;pointer-events:none;';
			document.body.appendChild(toastEl);
		}
		toastEl.textContent = msg;
		toastEl.style.opacity = '1';
		clearTimeout(toast._t);
		toast._t = setTimeout(() => (toastEl.style.opacity = '0'), 1800);
	}

	document.addEventListener('keydown', (e) => {
		if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
		if (e.metaKey || e.ctrlKey || e.altKey) return;
		const k = e.key.toLowerCase();
		if (k === 'j') {
			ensureMounted();
			togglePanel();
		} else if (k === 's') {
			anchorCurrentSub();
		} else if (k === 'h') {
			state.isEnabled = !state.isEnabled;
			toast(state.isEnabled ? 'Subs on' : 'Subs off');
		} else if (k === 'i') {
			state.position = state.position === 'bottom' ? 'top' : 'bottom';
			set(KEYS.position, state.position);
			if (overlay) overlay.className = state.position;
		} else if (k === 'b') {
			rewindToLastSub();
		} else if (k === 'z') {
			adjustAlignment(e.shiftKey ? -1000 : -200);
		} else if (k === 'x') {
			adjustAlignment(e.shiftKey ? 1000 : 200);
		}
	});

	function bootstrap() {
		ensureMounted();
	}
	new MutationObserver(bootstrap).observe(document.documentElement, { childList: true, subtree: true });
	bootstrap();
	setInterval(bootstrap, 1000);
	setInterval(tick, 50);
})();

// SPDX-License-Identifier: GPL-3.0-or-later
//
// Merge duplicate pitch accents in Hachidori's popup (bee-san/hachidori#209).
//
// When two or more pitch accent dictionaries give a word exactly the same
// patterns, the popup lists them once, with every one of those dictionaries'
// names. A dictionary whose patterns differ in any way keeps its own line, so
// nothing a dictionary says is hidden.
(function () {
  "use strict";

  const watched = new WeakSet();

  // What a dictionary says: its patterns, with any tags on them, in order.
  function patternsOf(group) {
    return [...group.querySelectorAll(".pronunciation")].map(item => [
      item.dataset.pronunciationType ?? "",
      item.dataset.pronunciation ?? item.textContent.trim(),
      item.querySelector(".pronunciation-tag-list")?.textContent.trim() ?? "",
    ].join("\u0000")).join("\u0001");
  }

  function merge(list) {
    list.classList.add("hd-pitch-merged");
    const kept = new Map();
    for (const group of list.querySelectorAll(":scope > .pronunciation-group")) {
      const key = patternsOf(group);
      const first = kept.get(key);
      if (!first) {
        kept.set(key, group);
        continue;
      }
      // The first dictionary's line names this one too, and its patterns' labels say so.
      const tag = group.querySelector(".gsm-hoshidicts-pitch-source");
      if (tag) first.querySelector(".pronunciation-group-tag-list")?.append(tag);
      const names = [...first.querySelectorAll(".gsm-hoshidicts-pitch-source")].map(source => source.textContent.trim());
      for (const item of first.querySelectorAll(".pronunciation")) {
        const label = `${names.join(", ")}: ${item.dataset.pronunciation ?? ""}`;
        item.title = label;
        item.setAttribute("aria-label", label);
      }
      group.hidden = true;
    }
    // One line left reads as one dictionary's: no "1." in front of it.
    const shown = list.querySelectorAll(":scope > .pronunciation-group:not([hidden])").length;
    list.dataset.count = String(shown);
  }

  function apply(root) {
    for (const list of root.querySelectorAll(".pronunciation-group-list:not(.hd-pitch-merged)")) merge(list);
  }

  // The popup re-renders inside one root for each lookup, entry and child
  // popup, so the root is watched rather than each popup.
  function watch() {
    const root = document.querySelector("hachidori-host")?.shadowRoot;
    if (!root) return;
    apply(root);
    if (watched.has(root)) return;
    watched.add(root);
    new MutationObserver(() => apply(root)).observe(root, { childList: true, subtree: true });
  }

  window.addEventListener("hachidori-popup-shown", watch);
  watch();
})();

scripts.css:
/* SPDX-License-Identifier: GPL-3.0-or-later */
/* A merged dictionary's line stays hidden, whatever else lays the lines out
   (Pitch accents in a row shows every line). */
.hd-pitch-merged > .pronunciation-group[hidden] {
  display: none;
}
/* The names on a merged line sit together. */
.hd-pitch-merged .pronunciation-group-tag-list {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 3px;
  vertical-align: middle;
}

/* SPDX-License-Identifier: GPL-3.0-or-later */
/* Pitch accents in a row (bee-san/hachidori#642): each pitch accent
   dictionary's patterns sit side by side under the headword, wrapping onto the
   next line when the popup runs out of room, instead of one numbered line per
   dictionary. */
.gsm-hoshidicts-pitch-metadata .pronunciation-group-list {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 14px;
  padding-left: 0;
  list-style: none;
}
.gsm-hoshidicts-pitch-metadata .pronunciation-group {
  display: block;
}
/* A dictionary with several patterns keeps them on its line. */
.gsm-hoshidicts-pitch-metadata .pronunciation-list {
  display: inline;
  padding-left: 0;
  list-style: none;
}
.gsm-hoshidicts-pitch-metadata .pronunciation-list .pronunciation {
  display: inline;
}
.gsm-hoshidicts-pitch-metadata .pronunciation-list .pronunciation + .pronunciation {
  margin-left: 0.6em;
}

scripts.javascript:
// SPDX-License-Identifier: GPL-3.0-or-later
//
// Texthooker view for Hachidori's search page (docs/search-history.md).
//
// Turns the search page into a texthooker: the lines it keeps, newest at the
// bottom, scrolling along as they arrive, with the number of lines and of
// Japanese characters, their times when you want them, a pause for the
// Clipboard monitor, and an Edit and a Delete button on each line. Hover a
// word with Hachidori's activation key to look it up as on any page, or click
// it. The results show beside the lines, in the search page's results area.
//
// Install: switch on Settings → Advanced → Search history, which is off until
// you do, install this package from Settings → Advanced → User scripts →
// Script Store (or add this file there with Import files), and let Hachidori
// run user scripts (Chrome: Allow User Scripts on the extension's details
// page; Firefox: Settings asks). Open the search page and switch on its
// Clipboard monitor; a program that copies each new line, such as Textractor
// with its clipboard extension, then fills the list.
//
// It uses only HDSearchHistory, the search page's public history API, and
// does nothing on other pages, where user scripts run too. Inspired by
// texthooker-ui (https://github.com/Renji-XD/texthooker-ui, MIT, Copyright (c)
// 2023 Renji-xD); no code is taken from it. It has no websocket client, as
// texthooker-ui has for Textractor's and mpv's plugins: the lines come from the
// search page's history, which the Clipboard monitor fills with what those
// programs copy, and the search page opens no connection of its own.
(function () {
  "use strict";
  const history = globalThis.HDSearchHistory;
  if (!history || document.getElementById("hd-texthooker")) return;

  // Han, Hiragana and Katakana that are not punctuation or symbols, as the
  // search page's cursor stops on them.
  const JAPANESE = /(?=[\p{scx=Han}\p{scx=Hiragana}\p{scx=Katakana}])[^\p{P}\p{S}]/gu;
  const characters = text => text.match(JAPANESE)?.length ?? 0;
  const time = new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" });

  const style = document.createElement("style");
  style.textContent = `
    #hd-texthooker { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; gap: 6px; }
    body.search-page:has(#hd-texthooker) .search-results { flex: 1 1 0; }
    #hd-texthooker .hd-th-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px;
      color: var(--text-dim); font-size: var(--font-caption); }
    #hd-texthooker .hd-th-bar label { display: inline-flex; align-items: center; gap: 4px; }
    #hd-texthooker .hd-th-stats { margin-right: auto; }
    #hd-texthooker ol { flex: 1 1 auto; min-height: 0; margin: 0; padding: 4px 0; overflow-y: auto; list-style: none;
      border: 1px solid var(--border); border-radius: var(--radius-surface); background: var(--surface); }
    #hd-texthooker li { display: flex; align-items: baseline; gap: 8px; padding: 4px 10px; }
    #hd-texthooker li + li { border-top: 1px solid var(--border); }
    #hd-texthooker time { display: none; flex: none; color: var(--text-dim); font-size: var(--font-caption);
      font-variant-numeric: tabular-nums; }
    #hd-texthooker.hd-th-times time { display: inline; }
    #hd-texthooker .hd-th-text { flex: 1; margin: 0; font-size: 20px; line-height: 1.6; white-space: pre-wrap;
      overflow-wrap: anywhere; cursor: text; }
    #hd-texthooker .hd-th-text[contenteditable] { outline: 2px solid var(--accent); outline-offset: 2px; cursor: auto; }
    #hd-texthooker .hd-th-actions { flex: none; display: flex; gap: 4px; opacity: 0; }
    #hd-texthooker li:is(:hover, :focus-within) .hd-th-actions { opacity: 1; }
    #hd-texthooker .hd-th-actions button, #hd-texthooker .hd-th-bar button { min-height: 28px; padding: 2px 8px; }
  `;
  document.head.append(style);

  const panel = document.createElement("section");
  panel.id = "hd-texthooker";
  panel.setAttribute("aria-label", "Texthooker");
  const bar = document.createElement("div");
  bar.className = "hd-th-bar";
  const stats = document.createElement("span");
  stats.className = "hd-th-stats";
  const timesLabel = document.createElement("label");
  const times = document.createElement("input");
  times.type = "checkbox";
  timesLabel.append(times, "Times");
  const pause = document.createElement("button");
  pause.type = "button";
  pause.className = "ghost hd-th-pause";
  bar.append(stats, timesLabel, pause);
  const list = document.createElement("ol");
  list.setAttribute("aria-label", "Kept lines");
  panel.append(bar, list);
  document.getElementById("search-results").before(panel);

  const items = new Map();
  function renderStats() {
    let count = 0;
    for (const kept of items.values()) count += kept.characters;
    stats.textContent = `${items.size} ${items.size === 1 ? "line" : "lines"} · ${count} characters`;
  }
  function renderPause() {
    pause.textContent = history.clipboardPaused ? "Resume clipboard" : "Pause clipboard";
    pause.setAttribute("aria-pressed", String(history.clipboardPaused));
  }

  // One line: its time, its text, and its Edit and Delete buttons. A line
  // break after each item ends a lookup there, so a word never runs on into
  // the next line.
  function item(line) {
    const entry = document.createElement("li");
    const stamp = document.createElement("time");
    const text = document.createElement("p");
    text.className = "hd-th-text";
    text.lang = "ja";
    const actions = document.createElement("span");
    actions.className = "hd-th-actions";
    const edit = document.createElement("button");
    edit.type = "button";
    edit.className = "ghost";
    edit.textContent = "Edit";
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "ghost";
    remove.textContent = "Delete";
    actions.append(edit, remove);
    entry.append(stamp, text, actions);
    const kept = { entry, stamp, text, line };
    edit.addEventListener("click", () => startEdit(kept));
    text.addEventListener("dblclick", () => startEdit(kept));
    remove.addEventListener("click", () => { history.remove(line.id).catch(failed); });
    text.addEventListener("click", event => lookUpAt(kept, event));
    show(kept, line);
    return kept;
  }

  function show(kept, line) {
    kept.line = line;
    kept.characters = characters(line.text);
    kept.entry.dataset.id = String(line.id);
    kept.stamp.dateTime = new Date(line.at).toISOString();
    kept.stamp.textContent = time.format(line.at);
    kept.text.textContent = line.text;
    kept.entry.querySelector("button").setAttribute("aria-label", `Edit: ${line.text}`);
    kept.entry.querySelector("button:last-child").setAttribute("aria-label", `Delete: ${line.text}`);
  }

  // Lines stay in the order they were kept, newest at the bottom, whichever
  // arrives first: the list read at the start or a line kept meanwhile. While
  // the list is scrolled to its end it stays there, as lines arrive and as the
  // page around it changes size (the searched text appears after a search).
  // Scrolling up unpins it and scrolling back to the end pins it again. A
  // scroll event for the position follow() set can arrive after the list has
  // shrunk, when that position no longer looks like the end: it keeps the
  // list pinned.
  let pinned = true;
  let followed = null;
  const follow = () => {
    if (!pinned) return;
    list.scrollTop = list.scrollHeight;
    followed = list.scrollTop;
  };
  list.addEventListener("scroll", () => {
    const atEnd = list.scrollHeight - list.scrollTop - list.clientHeight < 24;
    pinned = atEnd || (pinned && list.scrollTop === followed);
  });
  new ResizeObserver(follow).observe(list);
  // A line's place is found from the end: lines arrive in order, but for one
  // from another page that overtakes another's.
  function add(line, newest) {
    if (items.has(line.id)) return;
    const kept = item(line);
    items.set(line.id, kept);
    let later = null;
    for (let entry = list.lastElementChild; entry && Number(entry.dataset.id) > line.id; entry = entry.previousElementSibling) {
      later = entry;
    }
    if (later) later.before(kept.entry, "\n");
    else list.append(kept.entry, "\n");
    if (newest) follow();
  }

  function drop(id) {
    const kept = items.get(id);
    if (!kept) return;
    kept.entry.nextSibling?.remove();
    kept.entry.remove();
    items.delete(id);
  }

  const failed = (error) => { console.warn("texthooker: the search history refused the change:", error); };

  // Editing: Enter or leaving the line saves it, Escape gives up, and a line
  // left empty is deleted.
  function startEdit(kept) {
    if (kept.text.isContentEditable) return;
    const editing = new AbortController();
    kept.text.contentEditable = "plaintext-only";
    kept.text.focus();
    getSelection().selectAllChildren(kept.text);
    const finish = (save) => {
      editing.abort();
      kept.text.removeAttribute("contenteditable");
      const edited = kept.text.textContent.trim();
      kept.text.textContent = kept.line.text;
      if (!save || edited === kept.line.text) return;
      (edited ? history.edit(kept.line.id, edited) : history.remove(kept.line.id)).catch(failed);
    };
    kept.text.addEventListener("keydown", (event) => {
      if (event.isComposing || !["Enter", "Escape"].includes(event.key) || event.shiftKey) return;
      event.preventDefault();
      finish(event.key === "Enter");
      kept.text.blur();
    }, { signal: editing.signal });
    kept.text.addEventListener("blur", () => finish(true), { signal: editing.signal });
  }

  // A click on a word looks it up, unless it ends a selection or an edit. The
  // caret falls between two characters (graphemes: a kana and its voiced mark,
  // a kanji and its variation selector): the glyph clicked is the one after it
  // or, for a click on a glyph's right half, the one before it, which can end
  // the row above the caret's. A click beside the text looks up nothing.
  const graphemes = new Intl.Segmenter(undefined, { granularity: "grapheme" });
  function lookUpAt(kept, { clientX, clientY }) {
    if (kept.text.isContentEditable || getSelection()?.isCollapsed === false) return;
    const caret = document.caretPositionFromPoint?.(clientX, clientY);
    const range = caret ? null : document.caretRangeFromPoint?.(clientX, clientY);
    const node = caret?.offsetNode ?? range?.startContainer;
    if (node?.nodeType !== Node.TEXT_NODE || !kept.text.contains(node)) return;
    const offset = caret?.offset ?? range.startOffset;
    const segments = graphemes.segment(node.data);
    const glyph = document.createRange();
    const clicked = (segment) => {
      if (!segment) return false;
      glyph.setStart(node, segment.index);
      glyph.setEnd(node, segment.index + segment.segment.length);
      const { left, right, top, bottom } = glyph.getBoundingClientRect();
      return clientX >= left && clientX <= right && clientY >= top && clientY <= bottom;
    };
    const hit = [segments.containing(offset), offset > 0 ? segments.containing(offset - 1) : undefined].find(clicked);
    if (hit) void history.lookUp(node, hit.index);
  }

  times.addEventListener("change", () => { panel.classList.toggle("hd-th-times", times.checked); });
  pause.addEventListener("click", () => {
    history.clipboardPaused = !history.clipboardPaused;
    renderPause();
  });
  history.addEventListener("line", (event) => {
    add(event.detail, true);
    renderStats();
  });
  history.addEventListener("change", ({ detail: change }) => {
    if (change.type === "edit") {
      const kept = items.get(change.line.id);
      if (kept) show(kept, change.line);
    } else if (change.type === "remove") {
      drop(change.id);
    } else if (change.type === "clear") {
      for (const id of [...items.keys()]) drop(id);
    } else if (change.type === "prune") {
      for (const id of [...items.keys()]) if (id < change.before) drop(id);
    }
    renderStats();
  });

  renderPause();
  renderStats();
  void history.list().then((lines) => {
    for (const line of lines) add(line, false);
    follow();
    renderStats();
  });
}());
